def __new__(cls, data=None, dtype=None, copy: bool | None=None, name=None, tupleize_cols: bool=True) -> Self:
    from pandas.core.indexes.range import RangeIndex
    name = maybe_extract_name(name, data, cls)
    if dtype is not None:
        dtype = pandas_dtype(dtype)
    data_dtype = getattr(data, 'dtype', None)
    refs = None
    if not copy and isinstance(data, (ABCSeries, Index)):
        refs = data._references
    data, copy = cls._maybe_copy_array_input(data, copy, dtype)
    if isinstance(data, (range, RangeIndex)):
        result = RangeIndex(start=data, copy=bool(copy), name=name)
        if dtype is not None:
            return result.astype(dtype, copy=False)
        return result
    elif is_ea_or_datetimelike_dtype(dtype):
        if isinstance(data, (set, frozenset)):
            data = list(data)
    elif is_ea_or_datetimelike_dtype(data_dtype):
        pass
    elif isinstance(data, (np.ndarray, ABCMultiIndex)):
        if isinstance(data, ABCMultiIndex):
            data = data._values
        if data.dtype.kind not in 'iufcbmM':
            data = com.asarray_tuplesafe(data, dtype=_dtype_obj)
    elif isinstance(data, (ABCSeries, Index)):
        pass
    elif is_scalar(data):
        raise cls._raise_scalar_data_error(data)
    elif hasattr(data, '__array__'):
        return cls(np.asarray(data), dtype=dtype, copy=copy, name=name)
    elif not is_list_like(data) and (not isinstance(data, memoryview)):
        raise cls._raise_scalar_data_error(data)
    else:
        if tupleize_cols:
            if is_iterator(data):
                data = list(data)
            if data and all((isinstance(e, tuple) for e in data)):
                from pandas.core.indexes.multi import MultiIndex
                return MultiIndex.from_tuples(data, names=name)
        if not isinstance(data, (list, tuple)):
            data = list(data)
        if len(data) == 0:
            data = np.array(data, dtype=object)
        if len(data) and isinstance(data[0], tuple):
            data = com.asarray_tuplesafe(data, dtype=_dtype_obj)
    try:
        arr = sanitize_array(data, None, dtype=dtype, copy=bool(copy))
    except ValueError as err:
        if 'index must be specified when data is not list-like' in str(err):
            raise cls._raise_scalar_data_error(data) from err
        if 'Data must be 1-dimensional' in str(err):
            raise ValueError('Index data must be 1-dimensional') from err
        raise
    arr = ensure_wrapped_if_datetimelike(arr)
    klass = cls._dtype_to_subclass(arr.dtype)
    arr = klass._ensure_array(arr, arr.dtype, copy=False)
    return klass._simple_new(arr, name, refs=refs)

@classmethod
def _ensure_array(cls, data, dtype, copy: bool):
    """
        Ensure we have a valid array to pass to _simple_new.
        """
    if data.ndim > 1:
        raise ValueError('Index data must be 1-dimensional')
    elif dtype == np.float16:
        raise NotImplementedError('float16 indexes are not supported')
    if copy:
        data = data.copy()
    return data

@final
@classmethod
def _dtype_to_subclass(cls, dtype: DtypeObj):
    if isinstance(dtype, ExtensionDtype):
        return dtype.index_class
    if dtype.kind == 'M':
        from pandas import DatetimeIndex
        return DatetimeIndex
    elif dtype.kind == 'm':
        from pandas import TimedeltaIndex
        return TimedeltaIndex
    elif dtype.kind == 'O':
        return Index
    elif issubclass(dtype.type, str) or is_numeric_dtype(dtype):
        return Index
    raise NotImplementedError(dtype)

@classmethod
def _with_infer(cls, *args, **kwargs):
    """
        Constructor that uses the 1.0.x behavior inferring numeric dtypes
        for ndarray[object] inputs.
        """
    result = cls(*args, **kwargs)
    if result.dtype == _dtype_obj and (not result._is_multi):
        values = lib.maybe_convert_objects(result._values)
        if values.dtype.kind in 'iufb':
            return Index(values, name=result.name, copy=False)
    return result

