def _cmp_method(self, other, op):
    """
        Wrapper used to dispatch comparison operations.
        """
    if self.is_(other):
        if op in {operator.eq, operator.le, operator.ge}:
            arr = np.ones(len(self), dtype=bool)
            if self._can_hold_na and (not isinstance(self, ABCMultiIndex)):
                arr[self.isna()] = False
            return arr
        elif op is operator.ne:
            arr = np.zeros(len(self), dtype=bool)
            if self._can_hold_na and (not isinstance(self, ABCMultiIndex)):
                arr[self.isna()] = True
            return arr
    if isinstance(other, (np.ndarray, Index, ABCSeries, ExtensionArray)) and len(self) != len(other):
        raise ValueError('Lengths must match to compare')
    if not isinstance(other, ABCMultiIndex):
        other = extract_array(other, extract_numpy=True)
    else:
        other = np.asarray(other)
    result = ops.comparison_op(self._values, other, op)
    return result

@final
def _logical_method(self, other, op):
    res_name = ops.get_op_result_name(self, other)
    lvalues = self._values
    rvalues = extract_array(other, extract_numpy=True, extract_range=True)
    res_values = ops.logical_op(lvalues, rvalues, op)
    return self._construct_result(res_values, name=res_name, other=other)

@final
def _construct_result(self, result, name, other):
    if isinstance(result, tuple):
        return (Index(result[0], name=name, dtype=result[0].dtype, copy=False), Index(result[1], name=name, dtype=result[1].dtype, copy=False))
    return Index(result, name=name, dtype=result.dtype, copy=False)

